 insert into public.lineage_seed_reviews(unit_id,source_id,raw_source_path)
 select md5('alhazmi:lineage:v1:'||path)::uuid,md5('alhazmi:source:bnabar-5150')::uuid,path from s on conflict(unit_id) do nothing;

update public.lineage_seed_reviews set source_id=md5('alhazmi:source:bnabar-5150')::uuid where source_id=md5('alhazmi:source:bnabar-139')::uuid and review_status='needs_review';

select (select count(*)::int from public.lineage_units) units,(select count(*)::int from public.lineage_seed_reviews) reviews,(select count(*)::int from public.sources) sources;
